import base64, hashlib, hmac, json

SECRET = b'ch06-demo-secret-key'


def b64url(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')


def b64url_dec(seg: str) -> bytes:
    return base64.urlsafe_b64decode(seg + '=' * (-len(seg) % 4))


def _seg(obj) -> str:
    return b64url(json.dumps(obj, separators=(',', ':'), sort_keys=True).encode('utf-8'))


def sign(header, payload, secret=SECRET) -> str:
    h, p = _seg(header), _seg(payload)
    sig = hmac.new(secret, (h + '.' + p).encode('ascii'), hashlib.sha256).digest()
    return h + '.' + p + '.' + b64url(sig)


def verify(token, now, secret=SECRET, allowed_alg=('HS256',)):
    parts = token.split('.')
    if len(parts) != 3:
        return False
    h_seg, p_seg, s_seg = parts
    if json.loads(b64url_dec(h_seg)).get('alg') not in allowed_alg:
        return False
    expected = hmac.new(secret, (h_seg + '.' + p_seg).encode('ascii'), hashlib.sha256).digest()
    if not hmac.compare_digest(expected, b64url_dec(s_seg)):
        return False
    return now < json.loads(b64url_dec(p_seg)).get('exp', 1 << 62)


tok = sign({'alg': 'HS256', 'typ': 'JWT'}, {'sub': 'u1', 'exp': 1700000100})
print('valid=' + str(verify(tok, 1700000000)))
